/* Retail Mercs heat goldens are generated by executing the original DOS and
 * Windows functions in Unicorn. External effects and RNG are isolated there.
 * Include combat.c only to reach the critical dispatcher for the separate
 * original weapon-slot removal check, without a probabilistic hit setup. */
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "../src/combat.c"
#include "../tests/fixtures/combat-validation/mercs_heat_cases.h"
#include "../tests/fixtures/combat-completion/original-locations.h"

static void check_heat(const mercs_heat_case *c)
{
    combat_unit u;
    int state, flags, events, got[7], want[7], i;
    memset(&u,0,sizeof u);
    u.human = c->human;
    u.heat_mark = (float)c->heat_q / 65536.0f;
    u.heat = (float)(c->heat_q + c->gain_q) / 65536.0f;
    u.sink_per_tick = (float)c->sink_q / 65536.0f;
    u.seq_ticks = (float)(c->elapsed-c->ticks);
    u.warn_ticks = (float)(c->warn_elapsed-c->ticks);
    u.shutdown = c->state==3;
    u.shutdown_pending = (c->flags&4)!=0;
    u.override = (c->flags&8)!=0;
    u.alarm_latch = (c->flags&4096)!=0;
    u.warn_latch = c->warn;
    u.invulnerable = c->human && c->invulnerable;
    u.no_heat = c->human && !c->heat_on;
    u.rng = (unsigned)c->seed;
    /* The heat oracle hooks BlowAmmo itself. A non-exploding legacy ammo
     * slot lets this test observe that dispatch without testing explosion
     * semantics; disappearance records the call. */
    u.bin_count=1; u.bins[0].id=10001; u.bins[0].weapon=0;
    u.ammo_pool_count=1; u.ammo_pools[0].rounds=1;
    u.weapon_count=1; u.weapons[0].ammo=1;
    u.slot_count[MEK_LA]=1; u.slots[MEK_LA][0]=10001;
    u.internal[MEK_LA]=100;
    combat_heat_dos=c->dos;
    combat_tick(&u,(float)c->ticks/COMBAT_TICKS_PER_S);
    state=u.destroyed ? 4 : u.shutdown ? 3 : u.restarted ? 0 : c->state;
    flags=(u.shutdown_pending?4:0)|(u.override?8:0)|(u.alarm_latch?4096:0);
    events=u.heat_warning|(u.seq_alarm<<1)|(u.auto_shutdown<<2)|
           (u.restarted<<3)|(u.destroyed<<4)|((u.slot_count[MEK_LA]==0)<<5);
    got[0]=(int)lrintf(u.heat*65536); got[1]=state; got[2]=flags;
    got[3]=u.warn_latch; got[4]=events; got[5]=(int)lrintf(u.seq_ticks); got[6]=(int)lrintf(u.warn_ticks);
    want[0]=c->want_heat_q; want[1]=c->want_state; want[2]=c->want_flags;
    want[3]=c->want_warn; want[4]=c->want_events; want[5]=c->want_elapsed; want[6]=c->want_warn_elapsed;
    for(i=0;i<7;i++) if(got[i]!=want[i]) {
        fprintf(stderr,"%s: field %d expected %d got %d\n",c->name,i,want[i],got[i]);
        assert(got[i]==want[i]);
    }
}

static void check_weapon_slots(int silent)
{
    combat_unit u;
    int i,k;
    memset(&u,0,sizeof u);
    u.weapon_count=2; u.human=1;
    u.weapons[0].item=4801; u.weapons[0].weapon=48; u.weapons[0].state=CW_READY;
    u.weapons[1].item=4802; u.weapons[1].weapon=48; u.weapons[1].state=CW_READY;
    for(i=0;i<MEK_LOC_COUNT;i++) {
        u.slot_count[i]=4; u.internal[i]=10;
        u.slots[i][0]=4801; u.slots[i][1]=8001; u.slots[i][2]=4801; u.slots[i][3]=4802;
    }
    crit_item(&u,MEK_RA+1,0,silent);
    assert(u.weapons[0].state==-1 && u.weapons[1].state==CW_READY);
    assert(u.weapons[0].destroyed && !u.weapons[1].destroyed);
    assert(u.crit_said_n==(silent?0:1));
    for(i=0;i<MEK_LOC_COUNT;i++) {
        assert(u.slot_count[i]==2 && u.slots[i][0]==8001 && u.slots[i][1]==4802);
        for(k=2;k<MEK_SLOTS;k++) assert(u.slots[i][k]==0);
    }
}

static void check_torso_spread(void)
{
    unsigned seed,seen=0;
    int i;
    combat_ct_split=3;
    for(seed=0;seed<30;seed++) {
        combat_unit u;
        unsigned rng=seed;
        memset(&u,0,sizeof u);
        for(i=0;i<MEK_LOC_COUNT;i++) { u.armor[i]=20; u.internal[i]=100; }
        combat_damage_at(&u,1,3,&rng);
        for(i=1;i<=3;i++) if(u.armor[i]==19) seen|=1u<<(i-1);
    }
    assert(seen==7); /* original rand(3) reaches both side torsos and CT */
}

static void check_location(const original_location_case *c)
{
    combat_unit u;
    unsigned seed, probe;
    int i;
    memset(&u,0,sizeof u);
    u.unit_class=c->unit_class; u.immobile=c->immobile; u.speed_gain=1;
    for(i=0;i<MEK_LOC_COUNT;i++) u.internal[i]=100;
    if(c->gone) u.loc_gone[c->gone-1]=1;
    for(seed=0;;seed++) { probe=seed; if(rand_n(&probe,100)==c->roll) break; }
    combat_destroy_location(&u,c->location,&seed);
    for(i=0;i<MEK_LOC_COUNT;i++) {
        if((int)lrintf(u.internal[i]*65536)!=c->internal[i] ||
           u.loc_gone[i]!=c->want_gone[i]) {
            fprintf(stderr,"location%d roll%d class%d: part%d structure%g gone%d\n",
                    c->location,c->roll,c->unit_class,i+1,u.internal[i],u.loc_gone[i]);
            assert((int)lrintf(u.internal[i]*65536)==c->internal[i]);
            assert(u.loc_gone[i]==c->want_gone[i]);
        }
    }
    assert(u.immobile==c->want_immobile);
    assert((int)lrintf(u.speed_gain*65536)==c->speed_q);
    assert(u.destroyed==c->destroyed);
}

static void check_location_survival_items(void)
{
    combat_unit u;
    unsigned seed=1;
    memset(&u,0,sizeof u);
    u.unit_class=1; u.speed_gain=1;
    u.weapon_count=1;
    u.weapons[0].item=4801; u.weapons[0].weapon=48; u.weapons[0].state=CW_READY;
    u.slot_count[MEK_RL]=1; u.slots[MEK_RL][0]=4801;
    u.internal[MEK_RL]=100;
    combat_destroy_location(&u,MEK_RL+1,&seed);
    assert(u.internal[MEK_RL]==1 && !u.loc_gone[MEK_RL]);
    assert(u.slot_count[MEK_RL]==0 && u.weapons[0].destroyed);
    /* A direct debug/destruction request still honors the original fatal
     * player's invulnerability check at the final unit-death service. */
    u.human=1; u.invulnerable=1;
    combat_destroy_location(&u,MEK_CT+1,&seed);
    assert(!u.destroyed && u.internal[MEK_CT]==0);
}

int main(void)
{
    size_t i;
    for(i=0;i<sizeof mercs_heat_cases/sizeof mercs_heat_cases[0];i++) check_heat(&mercs_heat_cases[i]);
    check_weapon_slots(0); check_weapon_slots(1); check_torso_spread();
    for(i=0;i<sizeof original_locations/sizeof original_locations[0];i++) check_location(&original_locations[i]);
    check_location_survival_items();
    printf("Mercs combat:62 original DOS/Windows heat cases,17 location-loss cases, weapon slots and torso spread pass\n");
    return 0;
}
